create table public.fefo_settings(id bigint generated by default as identity primary key,business_id bigint not null unique references public.businesses(id) on delete cascade,fefo_enabled boolean not null default true,deduction_mode text not null default 'automatic' check(deduction_mode in ('automatic','manual_suggestion')),expiry_grace_days integer not null default 30,auto_deduct_expired_stock boolean not null default false,notify_on_fefo_deduction boolean not null default true,min_stock_for_fefo integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.fefo_logs(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,product_id bigint not null references public.products(id) on delete cascade,stock_id bigint references public.stocks(id) on delete set null,sale_id bigint references public.sales(id) on delete set null,sale_detail_id bigint references public.sale_details(id) on delete set null,batch_no text,expire_date date,quantity_deducted integer not null default 0,quantity_remaining_after integer not null default 0,action_type text not null default 'sale_deduction',notes text,meta jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.subscription_plans(id bigint generated by default as identity primary key,name text not null,slug text not null unique,description text,price numeric(10,2) not null,currency varchar(3) not null default 'USD',billing_cycle text not null default 'monthly',trial_days integer not null default 0,is_active boolean not null default true,is_default boolean not null default false,features jsonb,limits jsonb,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.subscriptions(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,plan_id bigint not null references public.subscription_plans(id) on delete cascade,status text not null default 'active',trial_ends_at date,starts_at date not null,ends_at date,cancelled_at date,payment_method text,stripe_subscription_id text,stripe_customer_id text,metadata jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.subscription_invoices(id bigint generated by default as identity primary key,subscription_id bigint not null references public.subscriptions(id) on delete cascade,business_id bigint not null references public.businesses(id) on delete cascade,invoice_number text not null,invoice_date date not null,due_date date not null,subtotal numeric(10,2) not null,tax numeric(10,2) not null default 0,total numeric(10,2) not null,amount_paid numeric(10,2) not null default 0,status text not null default 'pending',payment_method text,stripe_invoice_id text,stripe_payment_intent_id text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,invoice_number));
create table public.subscription_payments(id bigint generated by default as identity primary key,invoice_id bigint not null references public.subscription_invoices(id) on delete cascade,business_id bigint not null references public.businesses(id) on delete cascade,payment_number text not null,amount numeric(10,2) not null,currency varchar(3) not null default 'USD',status text not null default 'pending',payment_method text,gateway text,gateway_transaction_id text,gateway_response text,paid_at timestamptz,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,payment_number));
create table public.usage_records(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,subscription_id bigint not null references public.subscriptions(id) on delete cascade,metric_name text not null,quantity integer not null default 0,recorded_at date not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.subscription_logs(id bigint generated by default as identity primary key,subscription_id bigint not null references public.subscriptions(id) on delete cascade,business_id bigint not null references public.businesses(id) on delete cascade,action text not null,old_data jsonb,new_data jsonb,performed_by uuid references public.app_users(id) on delete set null,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['fefo_settings','fefo_logs','subscriptions','subscription_invoices','subscription_payments','usage_records','subscription_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon,authenticated',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); end loop; end $$;
alter table public.subscription_plans enable row level security; revoke all on public.subscription_plans from anon,authenticated; grant select on public.subscription_plans to authenticated;
create policy fefo_settings_tenant on public.fefo_settings for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy fefo_logs_tenant on public.fefo_logs for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy subscription_plans_read on public.subscription_plans for select to authenticated using(true);
create policy subscriptions_tenant on public.subscriptions for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy subscription_invoices_tenant on public.subscription_invoices for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy subscription_payments_tenant on public.subscription_payments for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy usage_records_tenant on public.usage_records for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy subscription_logs_tenant on public.subscription_logs for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));